<script setup lang="ts">
import { computed, inject, onBeforeUnmount, ref, watch, type ComputedRef } from 'vue';
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter } from 'vue-router';
import { AlertTriangle, ArrowRight, CheckCircle2, FileCheck2, FileDiff, GitBranch, GitMerge, LoaderCircle, RefreshCw, ShieldCheck } from 'lucide-vue-next';
import type { BranchItem, MergeResolutionChoice, MergeResolutionDecision, MergeResolutionPreview, MergeResolutionResult, RepositoryPermissions, RepositorySettingsState } from '@oxen/shared';
import { post, queryString, request } from '../api';
import { useAppStore } from '../stores/app';
const props=defineProps<{base:string;branch:string}>();const emit=defineEmits<{changed:[];'source-updated':[commitId:string]}>();
const route=useRoute(),router=useRouter(),app=useAppStore();const permissions=inject<ComputedRef<RepositoryPermissions>>('repositoryPermissions');
const canExecute=computed(()=>permissions?.value.capabilities?.['merge.execute']===true);
const branches=ref<BranchItem[]>([]),defaultBranch=ref('main'),source=ref(''),target=ref(''),baseRef=ref(''),loading=ref(false),busy=ref(false),error=ref(''),preview=ref<MergeResolutionPreview>(),result=ref<MergeResolutionResult>(),selectedPath=ref('');
interface Decision {choice:MergeResolutionChoice|'';fields:Record<string,'source'|'target'|''>;content:string}
const decisions=ref<Record<string,Decision>>({});let generation=0;
const current=computed(()=>preview.value?.files.find(file=>file.path===selectedPath.value));
const currentDecision=computed(()=>decisions.value[selectedPath.value]);
const dirty=computed(()=>!result.value&&Object.values(decisions.value).some(item=>item.choice!==''||Object.values(item.fields).some(Boolean)||item.content!==''));
const finished=(path:string)=>{const item=decisions.value[path],file=preview.value?.files.find(file=>file.path===path);return !!item&&!!item.choice&&(item.choice!=='fields'||file?.conflicts.every(conflict=>item.fields[conflict.pointer]))&&(item.choice!=='manual'||item.content.length>0);};
const ready=computed(()=>!!preview.value?.canResolve&&preview.value.files.every(file=>finished(file.path))&&canExecute.value&&!loading.value&&!busy.value&&!result.value);
const choiceName=(value:MergeResolutionChoice)=>({source:'使用源分支',target:'使用目标分支',fields:'按字段合并',manual:'手工文本'}[value]);
const print=(value:unknown,missing=false)=>missing?'（此版本不存在）':typeof value==='string'?value:JSON.stringify(value,null,2)??'（未定义）';
async function mayLeave(){if(busy.value){app.notify('原生裁决正在执行，请等待结果后再切换。');return false;}if(!dirty.value)return true;const allow=await app.confirmAction('尚有未提交的冲突裁决，确认放弃并切换吗？',{title:'未保存的裁决',confirmLabel:'放弃并切换'});if(allow)decisions.value={};return allow;}
onBeforeRouteLeave(mayLeave);onBeforeRouteUpdate((to,from)=>to.fullPath===from.fullPath||mayLeave());
const unregister=app.registerDraftGuard(mayLeave);onBeforeUnmount(unregister);
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||busy.value){event.preventDefault();event.returnValue='';}}window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>{++generation;window.removeEventListener('beforeunload',beforeUnload);});
function reset(){preview.value=undefined;result.value=undefined;decisions.value={};selectedPath.value='';error.value='';baseRef.value='';}
async function loadBranches(){const current=++generation;loading.value=true;try{const [values,settings]=await Promise.all([request<BranchItem[]>(props.base+'/branches'),request<RepositorySettingsState>(props.base+'/settings')]);if(current!==generation)return;branches.value=values;defaultBranch.value=settings.policy.defaultBranch;source.value=typeof route.query.source==='string'?route.query.source:props.branch!==defaultBranch.value?props.branch:values.find(item=>item.name!==defaultBranch.value)?.name??'';target.value=typeof route.query.target==='string'?route.query.target:defaultBranch.value;baseRef.value=typeof route.query.base==='string'?route.query.base:'';if(source.value&&target.value&&source.value!==target.value)void compare(false);}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
async function choose(which:'source'|'target',value:string,element?:HTMLSelectElement){if(!await mayLeave()){if(element)element.value=which==='source'?source.value:target.value;return;}const version=generation;reset();if(which==='source')source.value=value;else target.value=value;await router.replace({query:{...route.query,source:source.value,target:target.value,base:undefined}});if(version!==generation)return;}
async function compare(confirm=true){if(confirm&&!await mayLeave())return;if(!source.value||!target.value||source.value===target.value)return;const current=++generation;loading.value=true;error.value='';result.value=undefined;preview.value=undefined;decisions.value={};selectedPath.value='';try{const value=await request<MergeResolutionPreview>(props.base+'/merge-resolution/compare'+queryString({source:source.value,target:target.value,...(baseRef.value?{base:baseRef.value}:{})}));if(current!==generation)return;preview.value=value;baseRef.value=value.baseCommitId;selectedPath.value=value.files[0]?.path??'';decisions.value=Object.fromEntries(value.files.map(file=>[file.path,{choice:'',fields:Object.fromEntries(file.conflicts.map(conflict=>[conflict.pointer,''])),content:''}]));}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
async function submit(){if(!ready.value||!preview.value)return;const captured=preview.value,current=generation;if(!await app.confirmAction(`将目标 ${captured.target} 的变化合入源工作分支 ${captured.source}，生成原生双亲提交并推送源分支。目标不会在此完成合并。之后需刷新 MR、重新提交复核。`,{title:'提交冲突裁决到源分支',confirmLabel:'提交并更新源分支'}))return;if(current!==generation)return;
  const resolutions:MergeResolutionDecision[]=captured.files.map(file=>{const item=decisions.value[file.path]!;return {path:file.path,choice:item.choice as MergeResolutionChoice,...(item.choice==='fields'?{fields:file.conflicts.map(conflict=>({pointer:conflict.pointer,choice:item.fields[conflict.pointer] as 'source'|'target'}))}:{}),...(item.choice==='manual'?{content:item.content}:{})};});
  busy.value=true;error.value='';try{const value=await post<MergeResolutionResult>(props.base+'/merge-resolution',{source:captured.source,target:captured.target,base:captured.baseCommitId,expectedSourceCommitId:captured.sourceCommitId,expectedTargetCommitId:captured.targetCommitId,fingerprint:captured.fingerprint,resolutions});if(current!==generation)return;result.value=value;decisions.value={};app.notify('源分支已更新，请刷新 MR 并重新提交复核');emit('source-updated',value.sourceCommitId);emit('changed');}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)busy.value=false;}}
watch(()=>[props.base,route.query.source,route.query.target],()=>{reset();void loadBranches();},{immediate:true});
</script>
<template>
  <section class="merge-resolution">
    <header class="resolution-heading"><div><h2>解决合并冲突</h2><p>核对共同基线、源与目标，逐项裁决；结果先更新源工作分支，保留重新复核的机会。</p></div><GitMerge :size="24"/></header>
    <form class="panel resolution-branches" @submit.prevent="compare()"><label>源工作分支<select :value="source" :disabled="loading||busy" @change="choose('source',($event.target as HTMLSelectElement).value,$event.target as HTMLSelectElement)"><option value="">选择源分支</option><option v-for="item in branches" :key="item.name" :value="item.name" :disabled="item.name===defaultBranch">{{item.name}}{{item.name===defaultBranch?' · 默认分支不可直接裁决写入':''}}</option></select></label><ArrowRight :size="19"/><label>目标分支<select :value="target" :disabled="loading||busy" @change="choose('target',($event.target as HTMLSelectElement).value,$event.target as HTMLSelectElement)"><option value="">选择目标分支</option><option v-for="item in branches" :key="item.name" :value="item.name">{{item.name}}</option></select></label><button class="btn" :disabled="loading||busy||!source||!target||source===target"><LoaderCircle v-if="loading" class="spin" :size="15"/><FileDiff v-else :size="15"/>比较真实冲突</button><label class="resolution-base">共同基线（服务端验证）<input v-model="baseRef" :disabled="loading||busy||!!preview" placeholder="自动确定共同祖先"/></label></form>
    <p v-if="error" class="error-state" role="alert">{{error}}<span>若提示恢复记录或推送结果待核对，请先检查源分支与作业记录，禁止盲目重试。</span></p>
    <div v-if="result" class="panel resolution-success" role="status"><CheckCircle2 :size="26"/><div><h3>源分支已更新，目标尚未合并</h3><p>请刷新 MR，并对受影响的样本、标签和附件重新提交复核。</p><code>{{result.source}} · {{result.sourceCommitId}}</code><small>原生父节点：{{result.parentIds.join(' + ')}}</small></div></div>
    <div v-if="loading&&!preview" class="empty"><LoaderCircle class="spin" :size="25"/><p>读取固定版本与原生冲突状态…</p></div>
    <template v-if="preview&&!result">
      <div class="resolution-pins"><span><GitBranch :size="13"/>基线 <code>{{preview.baseCommitId.slice(0,12)}}</code></span><span>源 <code>{{preview.sourceCommitId.slice(0,12)}}</code></span><span>目标 <code>{{preview.targetCommitId.slice(0,12)}}</code></span></div>
      <p v-for="warning in preview.warnings" :key="warning" class="resolution-warning"><AlertTriangle :size="15"/>{{warning}}</p>
      <p v-if="!canExecute" class="resolution-warning"><ShieldCheck :size="15"/>当前身份可以核对差异；执行裁决需要独立的合并能力。</p>
      <div v-if="!preview.files.length" class="panel empty"><CheckCircle2 :size="30"/><h3>没有需要裁决的原生冲突</h3><p>请返回合并请求，按正常审阅和合并流程继续。</p></div>
      <div v-else class="panel resolution-workspace"><aside><header><strong>{{preview.files.length}} 个冲突文件</strong><small>{{preview.native?'官方 Oxen 原生检查':'演示提供方比较'}}</small></header><button v-for="file in preview.files" :key="file.path" :class="{selected:selectedPath===file.path}" @click="selectedPath=file.path"><CheckCircle2 v-if="finished(file.path)" :size="16"/><AlertTriangle v-else :size="16"/><span><strong>{{file.path.split('/').pop()}}</strong><small>{{file.kind==='managed-row'?'样本内容':file.kind==='managed-label'?'人工标签':file.kind==='protected'?'受保护对象':file.kind}} · {{file.conflicts.length}} 处字段冲突</small></span></button></aside>
        <article v-if="current&&currentDecision" class="resolution-file"><header><code>{{current.path}}</code><p>{{current.summary}}</p></header><p v-if="current.blockedReason" class="resolution-blocked"><ShieldCheck :size="18"/>{{current.blockedReason}}</p><fieldset :disabled="busy||!canExecute"><div class="resolution-choice"><label v-for="choice in current.allowedChoices" :key="choice"><input v-model="currentDecision.choice" type="radio" :value="choice" :name="'resolution-'+current.path"/>{{choiceName(choice)}}</label></div>
          <div v-if="currentDecision.choice==='fields'" class="resolution-fields"><p class="muted">不冲突字段自动三方合并；每处冲突必须选择已有的源值或目标值，不能任意改写身份、规范和真值。</p><div v-if="!current.conflicts.length" class="resolution-auto"><CheckCircle2 :size="17"/>字段之间没有语义冲突，可合并双方的独立变更。</div><section v-for="conflict in current.conflicts" :key="conflict.pointer"><h4>{{conflict.pointer||'整个 JSON 值'}}</h4><details><summary>查看共同基线</summary><pre>{{print(conflict.base,conflict.baseMissing)}}</pre></details><div class="resolution-field-sides"><label :class="{chosen:currentDecision.fields[conflict.pointer]==='source'}"><span><input v-model="currentDecision.fields[conflict.pointer]" type="radio" :value="'source'" :name="'field-'+current.path+conflict.pointer"/>源分支 · {{preview.source}}</span><pre>{{print(conflict.source,conflict.sourceMissing)}}</pre></label><label :class="{chosen:currentDecision.fields[conflict.pointer]==='target'}"><span><input v-model="currentDecision.fields[conflict.pointer]" type="radio" :value="'target'" :name="'field-'+current.path+conflict.pointer"/>目标分支 · {{preview.target}}</span><pre>{{print(conflict.target,conflict.targetMissing)}}</pre></label></div></section></div>
          <label v-if="currentDecision.choice==='manual'" class="resolution-manual">手工文本结果<textarea v-model="currentDecision.content" rows="15" maxlength="1048576" spellcheck="false" placeholder="填写普通文本文件的完整裁决结果；不会作为命令执行。"/></label>
        </fieldset><details class="resolution-originals"><summary>查看固定版本的完整文本</summary><div><section><h4>源分支</h4><pre>{{current.sourceText??'此文件不存在、为二进制或超过内联文本预览限制。'}}</pre></section><section><h4>目标分支</h4><pre>{{current.targetText??'此文件不存在、为二进制或超过内联文本预览限制。'}}</pre></section></div><details><summary>共同基线</summary><pre>{{current.baseText??'基线不存在或没有内联文本。'}}</pre></details></details></article>
      </div><footer v-if="preview.files.length" class="resolution-footer"><p>{{preview.files.filter(file=>finished(file.path)).length}} / {{preview.files.length}} 项裁决已明确 · 提交会保留双亲血缘</p><button class="btn btn-ghost" :disabled="loading||busy" @click="compare()"><RefreshCw :size="15"/>重新比较</button><button class="btn btn-primary" :disabled="!ready" @click="submit"><LoaderCircle v-if="busy" class="spin" :size="16"/><FileCheck2 v-else :size="16"/>{{busy?'原生提交与推送中…':'提交裁决并更新源分支'}}</button></footer>
    </template>
  </section>
</template>
<style scoped>
.merge-resolution{color:var(--text)}.resolution-heading{display:flex;justify-content:space-between;align-items:center;gap:22px;margin-bottom:22px}.resolution-heading h2{font-size:22px}.resolution-heading p{font-size:13px;color:var(--muted);margin-top:10px;line-height:1.8}.resolution-heading>svg{color:var(--primary)}.resolution-branches{display:flex;align-items:end;gap:16px;padding:20px;flex-wrap:wrap}.resolution-branches>label{flex:1;min-width:180px}.resolution-branches>svg{margin-bottom:10px;color:var(--muted)}.resolution-branches label,.resolution-manual{display:flex;flex-direction:column;gap:9px;font-size:13px}.resolution-branches select,.resolution-branches input,.resolution-manual textarea{background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:5px;min-height:39px;padding:9px 11px;font-size:13px;width:100%}.resolution-branches .resolution-base{flex-basis:100%}.resolution-base input{font:12px Consolas,monospace;max-width:640px}.error-state{margin-top:18px}.error-state>span{display:block;font-size:12px;line-height:1.8;margin-top:8px}.resolution-success{display:flex;gap:17px;align-items:start;padding:25px;margin-top:23px}.resolution-success>svg{color:var(--success)}.resolution-success h3{font-size:18px}.resolution-success p{font-size:14px;line-height:1.8;margin:10px 0}.resolution-success code,.resolution-success small{display:block;font-size:12px;color:var(--muted);overflow-wrap:anywhere;line-height:1.8}.resolution-pins{display:flex;gap:20px;flex-wrap:wrap;padding:18px 0;font-size:12px;color:var(--muted)}.resolution-pins>span{display:flex;gap:7px;align-items:center}.resolution-warning{display:flex;gap:9px;align-items:start;font-size:13px;color:var(--muted);line-height:1.8;margin:8px 0}.resolution-warning svg{flex-shrink:0;margin-top:3px;color:var(--warning,#d4ab60)}.resolution-workspace{display:grid;grid-template-columns:280px minmax(0,1fr);margin-top:20px;overflow:hidden;min-height:440px}.resolution-workspace>aside{border-right:1px solid var(--line);background:var(--bg)}.resolution-workspace>aside>header{padding:20px;border-bottom:1px solid var(--line)}.resolution-workspace>aside strong{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.resolution-workspace>aside small{display:block;font-size:11px;color:var(--muted);line-height:1.7;margin-top:5px}.resolution-workspace>aside>button{display:flex;gap:10px;align-items:start;width:100%;text-align:left;padding:17px;border-bottom:1px solid var(--line)}.resolution-workspace>aside>button svg{flex-shrink:0;margin-top:3px;color:var(--muted)}.resolution-workspace>aside>button.selected{background:var(--surface-raised);box-shadow:inset 3px 0 var(--primary)}.resolution-workspace>aside>button.selected svg{color:var(--primary)}.resolution-file{min-width:0;padding:23px}.resolution-file>header code{display:block;font-size:12px;overflow-wrap:anywhere;line-height:1.8}.resolution-file>header p{font-size:13px;line-height:1.8;color:var(--muted);margin:10px 0 20px}.resolution-file fieldset{border:0;padding:0;min-width:0}.resolution-choice{display:flex;gap:15px;flex-wrap:wrap;padding:13px 0 20px;border-bottom:1px solid var(--line)}.resolution-choice label{display:flex;gap:7px;align-items:center;font-size:13px}.resolution-file input[type=radio]{accent-color:var(--primary)}.resolution-fields>.muted{font-size:12px;line-height:1.8;margin:18px 0}.resolution-fields>section{margin:20px 0}.resolution-file h4{font-size:13px;line-height:1.8;overflow-wrap:anywhere;margin-bottom:9px}.resolution-file details{font-size:12px;line-height:1.8;color:var(--muted)}.resolution-file summary{cursor:pointer}.resolution-file pre{background:var(--bg);border:1px solid var(--line);padding:13px;border-radius:5px;font:12px/1.8 Consolas,monospace;color:var(--text);white-space:pre-wrap;overflow-wrap:anywhere;max-height:380px;overflow:auto;margin-top:9px}.resolution-field-sides{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin-top:12px}.resolution-field-sides>label{display:flex;flex-direction:column;padding:12px;border:1px solid var(--line);border-radius:6px;cursor:pointer;min-width:0}.resolution-field-sides>label.chosen{border-color:var(--primary);background:color-mix(in srgb,var(--primary) 6%,var(--surface))}.resolution-field-sides>label>span{display:flex;gap:8px;align-items:center;font-size:12px}.resolution-manual{margin-top:22px}.resolution-manual textarea{font-family:Consolas,monospace;line-height:1.8;min-height:260px;background:var(--bg)}.resolution-originals{margin-top:24px;padding-top:18px;border-top:1px solid var(--line)}.resolution-originals>div{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:15px 0}.resolution-originals section{min-width:0}.resolution-blocked,.resolution-auto{display:flex;gap:10px;align-items:start;padding:14px;border:1px solid var(--line);border-radius:5px;font-size:13px;line-height:1.8;background:var(--surface-raised);margin:15px 0}.resolution-blocked{color:var(--danger)}.resolution-blocked svg,.resolution-auto svg{flex-shrink:0;margin-top:3px}.resolution-auto{color:var(--success)}.resolution-footer{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:20px 0;position:sticky;bottom:0;background:var(--bg);z-index:5}.resolution-footer p{font-size:12px;color:var(--muted);margin-right:auto;line-height:1.8}
@media(max-width:1050px){.resolution-workspace{grid-template-columns:230px minmax(0,1fr)}.resolution-field-sides,.resolution-originals>div{grid-template-columns:1fr}.resolution-file{padding:18px}}
@media(max-width:720px){.resolution-branches{padding:16px;gap:12px}.resolution-branches>label{flex-basis:100%}.resolution-branches>svg{display:none}.resolution-workspace{grid-template-columns:1fr}.resolution-workspace>aside{border-right:0;border-bottom:1px solid var(--line);max-height:240px;overflow:auto}.resolution-workspace>aside>button{padding:12px 16px}.resolution-footer .btn{font-size:12px}.resolution-heading h2{font-size:19px}}
</style>
